#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShGasAnalyz sh;  } Queue_GasPR;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintGasPR(DefinePaint)  {  QueueP(Queue_GasPR);  //  CShGasAnalyz* sh = (CShGasAnalyz*)PipeSh;  if ( sh ) if ( IsTypeOk )    {    if ( !p->m_bPressed )      {      memcpy( &p->sh, sh, sizeof( CShGasAnalyz ) );      }    }  //  return 1;  }static void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_GasPR* p = (Queue_GasPR*)base;  if ( !ISTypeOK ) return;  //  bool bSend = true;  //  if ( bSend )    {    p->send.SetNew( pVoid );    p->pPipe->SendData( p->send, bMessage );    }  p->m_bPressed = !bMessage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FillGas( SPriborBase* d, void* pp )  {  d->fnData = fnSendData;  Queue_GasPR* p = (Queue_GasPR*)pp;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddGasPR(DefineTegs)  {  //  AddQueueEx(Queue_GasPR);  //  CShGasAnalyz sh;  memcpy( &p->sh, &sh, sizeof(CShGasAnalyz) );  p->pSH = &p->sh;  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintGasPR;  //  AddPriborsPipe( def, teg, Buffer, p, &FillGas, id_GasAnalyz );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~